# core/router.ts:279-297  (core.router.callProcedure)
/**
 * @internal
 */
export function callProcedure(
  opts: ProcedureCallOptions & { procedures: ProcedureRouterRecord },
) {
  const { type, path } = opts;

  if (!(path in opts.procedures) || !opts.procedures[path]?._def[type]) {
    throw new TRPCError({
      code: 'NOT_FOUND',
      message: `No "${type}"-procedure on path "${path}"`,
    });
  }

  const procedure = opts.procedures[path] as AnyProcedure;

  return procedure(opts);
}

# core/router.ts:151-155  (core.router.isRouter)
function isRouter(
  procedureOrRouter: AnyProcedure | AnyRouter,
): procedureOrRouter is AnyRouter {
  return 'router' in procedureOrRouter._def;
}

# core/router.ts:299-342  (core.router.createCallerFactory)
export function createCallerFactory<TConfig extends AnyRootConfig>() {
  return function createCallerInner<
    TRouter extends Router<AnyRouterDef<TConfig>>,
  >(router: TRouter): RouterCaller<TRouter['_def']> {
    const def = router._def;

    return function createCaller(ctx) {
      const proxy = createRecursiveProxy(({ path, args }) => {
        // interop mode
        if (
          path.length === 1 &&
          procedureTypes.includes(path[0] as ProcedureType)
        ) {
          return callProcedure({
            procedures: def.procedures,
            path: args[0] as string,
            rawInput: args[1],
            ctx,
            type: path[0] as ProcedureType,
          });
        }

        const fullPath = path.join('.');
        const procedure = def.procedures[fullPath] as AnyProcedure;

        let type: ProcedureType = 'query';
        if (procedure._def.mutation) {
          type = 'mutation';
        } else if (procedure._def.subscription) {
          type = 'subscription';
        }

        return procedure({
          path: fullPath,
          rawInput: args[0],
          ctx,
          type,
        });
      });

      return proxy as ReturnType<RouterCaller<any>>;
    };
  };
}

